import re


def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("empty string")
    m = re.fullmatch(r'(\d*d)?(\d*h)?(\d*m)?(\d*s)?', s)
    if not m:
        raise ValueError(f"invalid duration: {s!r}")
    d, h, mi, sec = m.groups()
    total = 0
    if d:
        total += int(d[:-1]) * 86400
    if h:
        total += int(h[:-1]) * 3600
    if mi:
        total += int(mi[:-1]) * 60
    if sec:
        total += int(sec[:-1])
    return total
